param([switch]$Check,[switch]$Deploy,[switch]$Stop,[string]$ProjectRoot=(Split-Path $PSScriptRoot -Parent))
$ErrorActionPreference='Stop'
trap { if(-not ($Check -or $Deploy -or $Stop)){ Add-Type -AssemblyName System.Windows.Forms; [void][Windows.Forms.MessageBox]::Show($_.Exception.Message,'Nexus Office 部署助手') } else { [Console]::Error.WriteLine($_.Exception.Message) }; exit 1 }
. (Join-Path $PSScriptRoot 'customer-deploy-core.ps1')
if($Check){Get-CustomerDeploymentState $ProjectRoot | ConvertTo-Json -Depth 6; exit 0}
if($Deploy){Start-CustomerDeployment $ProjectRoot | ConvertTo-Json -Depth 4; exit 0}
if($Stop){Stop-CustomerDeployment $ProjectRoot | ConvertTo-Json -Depth 4; exit 0}

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[Windows.Forms.Application]::EnableVisualStyles()
$form=New-Object Windows.Forms.Form; $form.Text='Nexus Office | 客户一键部署助手'; $form.Size=New-Object Drawing.Size(980,680); $form.MinimumSize=New-Object Drawing.Size(820,560); $form.StartPosition='CenterScreen'; $form.Font=New-Object Drawing.Font('Microsoft YaHei UI',10); $form.BackColor=[Drawing.Color]::FromArgb(246,248,250)
$layout=New-Object Windows.Forms.TableLayoutPanel; $layout.Dock='Fill'; $layout.Padding=New-Object Windows.Forms.Padding(20); $layout.ColumnCount=1; $layout.RowCount=6; foreach($row in @(56,38,44, 'Percent,100',100,30)){ if($row -is [int]){[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Absolute',$row)))}else{[void]$layout.RowStyles.Add((New-Object Windows.Forms.RowStyle('Percent',100)))}}; $form.Controls.Add($layout)
$title=New-Object Windows.Forms.Label; $title.Text='Nexus Office   客户一键部署'; $title.Font=New-Object Drawing.Font('Microsoft YaHei UI',19,[Drawing.FontStyle]::Bold); $title.Dock='Fill'; $layout.Controls.Add($title,0,0)
$status=New-Object Windows.Forms.Label; $status.Text='正在检查 Docker Desktop…'; $status.Dock='Fill'; $status.ForeColor=[Drawing.Color]::FromArgb(40,90,180); $layout.Controls.Add($status,0,1)
$actions=New-Object Windows.Forms.FlowLayoutPanel; $actions.Dock='Fill'; $actions.WrapContents=$false; $layout.Controls.Add($actions,0,2)
function New-Button([string]$Text,[int]$Width=130){$b=New-Object Windows.Forms.Button; $b.Text=$Text; $b.Size=New-Object Drawing.Size($Width,34); $b.Margin=New-Object Windows.Forms.Padding(0,0,10,0); $b.FlatStyle='Flat'; $b.BackColor=[Drawing.Color]::White; [void]$actions.Controls.Add($b); return $b}
$check=New-Button '重新检测'; $deploy=New-Button '一键部署并打开网页' 190; $deploy.Enabled=$false; $deploy.BackColor=[Drawing.Color]::FromArgb(34,106,221); $deploy.ForeColor=[Drawing.Color]::White; $dockerLink=New-Button '安装 Docker Desktop' 160; $stop=New-Button '停止项目' 110
$grid=New-Object Windows.Forms.DataGridView; $grid.Dock='Fill'; $grid.ReadOnly=$true; $grid.AllowUserToAddRows=$false; $grid.RowHeadersVisible=$false; $grid.SelectionMode='FullRowSelect'; $grid.MultiSelect=$false; $grid.AutoSizeColumnsMode='Fill'; $grid.BackgroundColor=[Drawing.Color]::White; $grid.BorderStyle='None'; [void]$grid.Columns.Add('name','检查项'); [void]$grid.Columns.Add('state','状态'); [void]$grid.Columns.Add('detail','说明'); $grid.Columns[0].FillWeight=22; $grid.Columns[1].FillWeight=16; $grid.Columns[2].FillWeight=62; $layout.Controls.Add($grid,0,3)
$log=New-Object Windows.Forms.TextBox; $log.Dock='Fill'; $log.Multiline=$true; $log.ReadOnly=$true; $log.ScrollBars='Vertical'; $log.BackColor=[Drawing.Color]::White; $log.BorderStyle='FixedSingle'; $layout.Controls.Add($log,0,4)
$footer=New-Object Windows.Forms.Label; $footer.Text='需要联网；安装 Docker 或启用 WSL 时可能出现 Windows 管理员确认或重启提示。'; $footer.Dock='Fill'; $footer.ForeColor=[Drawing.Color]::DimGray; $layout.Controls.Add($footer,0,5)
$script:job=$null; $script:handle=$null; $script:output=$null; $script:outputIndex=0; $script:mode=''; $script:last=$null
function Start-Work([string]$Mode){if($script:job){return}; $script:mode=$Mode; $check.Enabled=$false; $deploy.Enabled=$false; $dockerLink.Enabled=$false; $stop.Enabled=$false; if($Mode -ne 'check'){$log.Clear()}; $script:outputIndex=0; $script:job=[PowerShell]::Create(); $script:output=New-Object 'System.Management.Automation.PSDataCollection[psobject]'; $code=if($Mode -eq 'check'){'param($core,$root) . $core; Get-CustomerDeploymentState $root'}elseif($Mode -eq 'deploy'){'param($core,$root) . $core; Start-CustomerDeployment $root'}else{'param($core,$root) . $core; Stop-CustomerDeployment $root'}; [void]$script:job.AddScript($code).AddArgument((Join-Path $PSScriptRoot 'customer-deploy-core.ps1')).AddArgument($ProjectRoot); $script:handle=$script:job.BeginInvoke($null,$script:output); $status.Text=if($Mode -eq 'check'){'正在检查部署条件…'}elseif($Mode -eq 'deploy'){'正在部署，请保持窗口打开…'}else{'正在停止项目…'}; $status.ForeColor=[Drawing.Color]::FromArgb(40,90,180)}
$timer=New-Object Windows.Forms.Timer; $timer.Interval=300; $timer.Add_Tick({if($script:output){while($script:outputIndex -lt $script:output.Count){$entry=$script:output[$script:outputIndex++]; if($entry -is [string]){$log.AppendText($entry+[Environment]::NewLine)} }}; if(-not $script:job -or -not $script:handle.IsCompleted){return}; try{$result=@($script:job.EndInvoke($script:handle)); if($script:job.HadErrors){throw $script:job.Streams.Error[0].Exception}; if($script:mode -eq 'check'){$script:last=$result[-1]; $grid.Rows.Clear(); foreach($item in $script:last.Rows){$i=$grid.Rows.Add($item.Name,$item.State,$item.Detail); if(-not $item.Passed){$grid.Rows[$i].DefaultCellStyle.ForeColor=[Drawing.Color]::Firebrick}}; $deploy.Enabled=$script:last.CanAttempt; $dockerLink.Enabled=-not [bool]$script:last.Desktop; $status.Text=if($script:last.Allowed){'允许部署：点击“一键部署并打开网页”。'}elseif($script:last.CanAttempt){'可以自动准备 Docker，点击“一键部署并打开网页”。'}else{'暂不能部署：处理红色检查项后重新检测。'}; $status.ForeColor=if($script:last.Allowed -or $script:last.CanAttempt){[Drawing.Color]::ForestGreen}else{[Drawing.Color]::Firebrick}}elseif($script:mode -eq 'deploy'){$status.Text='部署完成，网页已打开。'; $status.ForeColor=[Drawing.Color]::ForestGreen}elseif($script:mode -eq 'stop'){$status.Text='项目已停止，数据已保留。'; $status.ForeColor=[Drawing.Color]::ForestGreen}}catch{$status.Text='部署未完成：'+$_.Exception.Message; $status.ForeColor=[Drawing.Color]::Firebrick; $log.AppendText($_.Exception.Message+[Environment]::NewLine)}finally{$script:job.Dispose();$script:job=$null;$script:output=$null;$check.Enabled=$true;$stop.Enabled=$true}})
$check.Add_Click({Start-Work 'check'}); $deploy.Add_Click({Start-Work 'deploy'}); $stop.Add_Click({Start-Work 'stop'}); $dockerLink.Add_Click({Start-Process 'https://www.docker.com/products/docker-desktop/'})
$form.Add_Shown({$timer.Start(); Start-Work 'check'}); try{[void]$form.ShowDialog()}finally{$timer.Stop();$timer.Dispose();if($script:job){$script:job.Stop();$script:job.Dispose()};$form.Dispose()}
